import{_ as t,a,c as n,ac as i}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse(`{"title":"第三册：培养技能 · Lesson 13 It's only me","description":"学习 强调句的焦点，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 13 It's only me","description":"学习 强调句的焦点，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 强调句的焦点，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 12 Life on a desert island","link":"/life/english/new-concept/book-3/unit-01/lesson-012"},"next":{"text":"第三册：培养技能 · Lesson 14 A noble gangster","link":"/life/english/new-concept/book-3/unit-01/lesson-014"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 12 Life on a desert island","link":"/life/english/new-concept/book-3/unit-01/lesson-012"},"next":{"text":"第三册：培养技能 · Lesson 14 A noble gangster","link":"/life/english/new-concept/book-3/unit-01/lesson-014"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-01/lesson-013.md","filePath":"life/english/new-concept/book-3/unit-01/lesson-013.md"}`),o={name:"life/english/new-concept/book-3/unit-01/lesson-013.md"};function s(l,e,r,h,d,c){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="第三册-培养技能-·-lesson-13-it-s-only-me" tabindex="-1">第三册：培养技能 · Lesson 13 It&#39;s only me <a class="header-anchor" href="#第三册-培养技能-·-lesson-13-it-s-only-me" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 13 It&#39;s only me&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>围绕意外装扮与身份误认，练习从人物视角解释一次惊吓。叙事要说明观察者看到了什么以及为何误会，而不是直接把结果提前揭示。学习强调句把身份、时间或原因放到焦点位置，同时保留普通句和强调句之间的事实一致性。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>disguise</td><td>/dɪsˈɡaɪz/</td><td>n.</td><td>伪装</td><td>wear a disguise</td></tr><tr><td>recognize</td><td>/ˈrekəɡnaɪz/</td><td>v.</td><td>认出</td><td>recognize a voice</td></tr><tr><td>costume</td><td>/ˈkɒstjuːm/</td><td>n.</td><td>戏装</td><td>a stage costume</td></tr><tr><td>startle</td><td>/ˈstɑːtl/</td><td>v.</td><td>使惊吓</td><td>startle a visitor</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>turn out to be — 最后发现原来是</li><li>at first sight — 初看时，强调初步印象</li></ul><h2 id="语法讲解-强调句的焦点" tabindex="-1">语法讲解：强调句的焦点 <a class="header-anchor" href="#语法讲解-强调句的焦点" aria-label="Permalink to &quot;语法讲解：强调句的焦点&quot;">​</a></h2><p>It is 或 was 加被强调部分再加 that 从句，可突出原句中的主语、宾语或状语；强调人时也可用 who。检查方法是去掉 it is/was 与 that/who，剩余成分通常能还原完整句子。强调句中的 it 不指代具体物品。不要与普通的 It is obvious that ... 主语从句结构混淆，后者不能按同样方式删掉框架。强调哪个成分会改变信息焦点，但并不改变基本事件或自动否定其他所有可能性。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>It was the gardener&#39;s voice that finally reassured the visitor.</p></blockquote><p>最终让访客安心的是园丁的声音。</p><p>It was ... that 强调主语 the gardener&#39;s voice；还原为 The gardener&#39;s voice finally reassured the visitor。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>It was yesterday when he called 不宜作为本课标准强调句答案；强调时间用 It was yesterday that he called。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>分别重读 mask、voice、laugh，体会焦点变化；朗读 It was ... that 时避免在 that 后产生不必要的长停顿。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>A tall figure stood behind the curtain. I thought a stranger had entered the room. It was my sister&#39;s laugh that made me relax.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句身份误会，最后用强调句说明消除误会的线索。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>先展示视觉误导，再交代推测，最后突出可靠的声音线索。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>还原例句为普通句。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The gardener&#39;s voice finally reassured the visitor.</p><p><strong>解析：</strong> 删除强调框架后保留完整主谓宾。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>用强调句突出主语：The mask frightened the child.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> It was the mask that frightened the child.</p><p><strong>解析：</strong> mask 放在焦点位置。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>例句的 it 指园丁吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不指。</p><p><strong>解析：</strong> 它是强调结构的形式成分。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：强调句的焦点。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-012">上一课</a> · <a href="/life/english/new-concept/book-3/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-01/lesson-014">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const g=t(o,[["render",s]]);export{p as __pageData,g as default};
